(() => {
 const root=document.querySelector('#demo');const project=new URLSearchParams(location.search).get('project');
 if(project==='lumina'){
 const outputs=[['Document','feature-portfolio.md','A portfolio, explained.','A product designer’s work, told through case studies and interactive examples.',['Who it is for: people exploring Vinny’s work and design approach.','Home introduces the work. Filters help visitors choose a type of project.','Case studies open as bottom sheets. The chat answers questions from a curated professional profile.']],['Packet','portfolio-packet.md','Keep the context together.','One place for the design story, behavior, and review links.',['Purpose: make the work easy to explore.','Design decisions: Geist, rounded surfaces, hover motifs, and a scroll-driven deck.','Review routes: Home, About, and the case-study sheets.']],['Deck','portfolio-deck.pptx','A story someone else can present.','Illustrative slide outline, not a generated PowerPoint file.',['01 / Introduce the designer and the work.','02 / Explore the case-study deck and filters.','03 / Show the interaction craft and ways to get in contact.']],['Ask','source-grounded answer','What happens when I filter work?','The chosen category updates the visible project set. The deck reorganizes around the matching projects.',['Source: portfolio home-motion.js and the work filter UI.','The selection is reflected in each button’s aria-pressed state.','This example is authored sample content, not an AI response.']],['Links','links.md','Open the experience.','A useful packet includes screens you can try.',['Home: /','About: /about-me/','Case study: /everkind/','Design engineering: /design-engineering/']]];
 root.innerHTML='<div class="demo-heading"><h2>From screen to shared context.</h2><span class="sample">Illustrative portfolio outputs</span></div><div class="tabs" aria-label="Output format"></div><article class="output" aria-live="polite"></article>';
 const tabs=root.querySelector('.tabs'),out=root.querySelector('.output');outputs.forEach((o,i)=>{const b=document.createElement('button');b.textContent=o[0];b.setAttribute('aria-pressed','false');b.onclick=()=>select(i);tabs.append(b)});
 function select(i){tabs.querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));const o=outputs[i];out.replaceChildren();const file=document.createElement('span');file.className='file';file.textContent=o[1];const h=document.createElement('h3');h.textContent=o[2];const p=document.createElement('p');p.textContent=o[3];const ul=document.createElement('ul');o[4].forEach(t=>{const li=document.createElement('li');li.textContent=t;ul.append(li)});const f=document.createElement('footer');f.textContent='Source: this portfolio · Sample content · No internal documents or live AI connection';out.append(file,h,p,ul,f)}select(0);
 }else if(project==='margo'){
 root.innerHTML='<div class="demo-heading"><h2>Behavior, in the margins.</h2><span class="sample">Illustrative handoff diagram</span></div><div class="checks"><label><input type="checkbox" data-notes checked>Show notes</label><label><input type="checkbox" data-gaps>Show sample gap</label></div><div class="output diagram"><div class="artboard"><img src="assets/about-light.png" alt="Captured About page"><span>About / Light</span></div><div><div class="notes"><button class="note" data-detail="The About page follows the same saved theme as Home. Switching themes updates the page without changing its content." aria-pressed="false"><strong>01 / Theme is a state.</strong><small>Keep it consistent across routes.</small></button><button class="note" data-detail="The photo marquee continues moving during hover. A reduced-motion preference removes the animation." aria-pressed="false"><strong>02 / Keep the photos moving.</strong><small>Respect reduced motion.</small></button><button class="note gap" data-detail="Illustrative gap: a reusable annotation card would need a defined component contract before handoff. This is a sample, not a finding from the portfolio." hidden aria-pressed="false"><strong>Build / Annotation card</strong><small>Sample component gap.</small></button></div><p class="note-detail" role="status">Select a note to read the rule behind the screen.</p></div></div>';
 root.querySelector('[data-notes]').onchange=e=>root.querySelectorAll('.note:not(.gap)').forEach(n=>n.hidden=!e.target.checked);root.querySelector('[data-gaps]').onchange=e=>root.querySelector('.gap').hidden=!e.target.checked;root.querySelectorAll('.note').forEach(b=>b.onclick=()=>{root.querySelectorAll('.note').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));root.querySelector('.note-detail').textContent=b.dataset.detail});
 }else{
 root.innerHTML='<div class="demo-heading"><h2>Useful feedback, close to the code.</h2><span class="sample">Illustrative portfolio audit</span></div><div class="audit-columns"><pre class="code"></pre><div class="audit-preview"><button type="button">Example button</button></div></div><div class="audit-actions"><button class="primary" data-run>Run sample audit</button><button data-fix disabled>Apply sample fixes</button></div><p class="audit-status" role="status">A deliberately imperfect sample, checked against portfolio styles.</p><ul class="findings" hidden></ul>';
 const code=root.querySelector('.code'),list=root.querySelector('.findings'),status=root.querySelector('.audit-status');code.textContent='.card {\n  background: #f5f5f5;\n  border-radius: 6px;\n  padding: 13px;\n}\nbutton:focus { outline: none; }';
 const findings=[['2','Hard-coded surface','Use the portfolio’s --paper or --panel token.'],['3','Inconsistent radius','Cards use 32px; buttons use a pill shape.'],['4','Off-scale padding','Use a consistent spacing value, such as 24px.'],['6','Focus removed','Restore a visible keyboard focus indicator.']];
 root.querySelector('[data-run]').onclick=()=>{list.hidden=false;list.innerHTML='';findings.forEach(([line,title,copy])=>{const li=document.createElement('li');const n=document.createElement('span');n.textContent='L'+line;const d=document.createElement('div');const s=document.createElement('strong');s.textContent=title;d.append(s,document.createTextNode(copy));li.append(n,d);list.append(li)});status.textContent='4 illustrative findings. Every item points to a concrete change.';root.querySelector('[data-fix]').disabled=false};
 root.querySelector('[data-fix]').onclick=()=>{root.querySelector('.audit-preview').classList.add('fixed');code.textContent='.card {\n  background: var(--paper);\n  border-radius: 32px;\n  padding: 24px;\n}\nbutton:focus-visible {\n  outline: 3px solid #8276ff;\n  outline-offset: 3px;\n}';status.textContent='Sample fixes applied. Focus the example button with Tab to check the ring.';list.hidden=true};
 }
})();
